package ru.funpay.tools;

import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.graphics.Typeface;
import android.graphics.drawable.*;
import android.view.*;
import android.widget.*;
import com.google.zxing.*;
import com.google.zxing.common.HybridBinarizer;
import com.google.zxing.integration.android.IntentIntegrator;
import org.json.JSONObject;
import java.io.*;

public final class WelcomeActivity extends Activity {
    Settings prefs;Palette p;Typeface font;LinearLayout body;final QrTransfer transfer=new QrTransfer();JSONObject pending;
    int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setTypeface(font);t.setIncludeFontPadding(false);t.setLineSpacing(dp(3),1.05f);t.setPadding(0,dp(6),0,dp(6));return t;}
    Button button(String label,int resource,Runnable run){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(14);b.setTypeface(Palette.weight(font,500));b.setTextColor(p.text);b.setIncludeFontPadding(false);b.setTextAlignment(View.TEXT_ALIGNMENT_GRAVITY);b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);b.setPadding(dp(16),dp(12),dp(16),dp(12));b.setMinHeight(dp(52));b.setStateListAnimator(null);GradientDrawable bg=new GradientDrawable();bg.setColor(p.surface);bg.setCornerRadius(dp(12));bg.setStroke(dp(1),p.line);b.setBackground(new RippleDrawable(android.content.res.ColorStateList.valueOf((p.accent&0xffffff)|0x22000000),bg,null));Drawable icon=getDrawable(resource).mutate();icon.setTint(p.accent);icon.setBounds(0,0,dp(22),dp(22));b.setCompoundDrawablesRelative(icon,null,null,null);b.setCompoundDrawablePadding(dp(12));b.setOnClickListener(v->run.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(6),0,dp(6));body.addView(b,lp);return b;}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);prefs=new Settings(this);if(new SessionStore(this).read()!=null&&getSharedPreferences("onboarding",0).getBoolean("complete",false)&&!getIntent().getBooleanExtra("configure",false)){startActivity(new Intent(this,MainActivity.class));finish();return;}if(saved!=null){transfer.id=saved.getString("qr_id","");transfer.total=saved.getInt("qr_total");for(int i=1;i<=transfer.total;i++)if(saved.containsKey("qr_"+i))transfer.chunks.put(i,saved.getString("qr_"+i));}String raw=getSharedPreferences("onboarding",0).getString("pending","");try{if(!raw.isEmpty())pending=new JSONObject(raw);}catch(Exception ignored){}render();AppUpdates.check(this,false);}
    void render(){p=new Palette(prefs.theme());font=Palette.typeface(this,prefs.font());getWindow().setStatusBarColor(p.bg);getWindow().setNavigationBarColor(p.bg);getWindow().getDecorView().setSystemUiVisibility(p.dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(p.bg);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(24),dp(28),dp(24),dp(24));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,-1));ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.brand_mark);logo.setScaleType(ImageView.ScaleType.FIT_START);body.addView(logo,new LinearLayout.LayoutParams(dp(52),dp(52)));body.addView(text("FunPay Pocket",14,p.muted));TextView title=text("Ваш FunPay.\nТеперь на телефоне.",28,p.text);title.setTypeface(Palette.weight(font,650));body.addView(title);body.addView(text("Подключите аккаунт и перенесите настройки расширения.",14,p.muted));
        JSONObject session=new SessionStore(this).read();body.addView(text("01 / Аккаунт",12,p.accent));body.addView(text(session==null?"Войдите на сайте FunPay":session.optString("name","Аккаунт подключён"),17,p.text));button(session==null?"Войти через FunPay":"Сменить аккаунт",R.drawable.ic_ui_user,()->startActivityForResult(new Intent(this,SiteActivity.class).putExtra("path","/account/login").putExtra("login",true),10));
        body.addView(text("02 / Настройки",12,p.accent));body.addView(text(pending==null?"QR из расширения или файл .fpconfig":"Настройки готовы к переносу",14,p.muted));button("Сканировать QR",R.drawable.ic_ui_qr,()->{transfer.reset();scan();});button("QR из изображения",R.drawable.ic_ui_image,()->startActivityForResult(new Intent(Intent.ACTION_GET_CONTENT).setType("image/*"),31));button("Выбрать .fpconfig",R.drawable.ic_ui_document,()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),30));
        if(transfer.total>0)body.addView(text("Прочитано QR: "+transfer.chunks.size()+" из "+transfer.total,13,p.accent));
        Button next=button("Открыть приложение",R.drawable.ic_ui_external,()->{if(new SessionStore(this).read()==null)return;if(pending!=null){stopService(new Intent(this,PresenceService.class));PeriodicPresence.schedule(this,false);prefs.serviceBeat(false);prefs.save(pending);JSONObject theme=pending.optJSONObject("fpToolsTheme");if(theme!=null){String id=theme.optString("sitePreset");for(String supported:Palette.IDS)if(supported.equals(id))prefs.theme(id);}getSharedPreferences("onboarding",0).edit().remove("pending").apply();}getSharedPreferences("onboarding",0).edit().putBoolean("complete",true).apply();startActivity(new Intent(this,MainActivity.class));finish();});next.setEnabled(session!=null);next.setAlpha(session==null?.45f:1f);if(session==null)body.addView(text("Сначала подключите аккаунт. Настройки можно перенести до входа или позже.",12,p.muted));setContentView(root);
    }
    @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("qr_id",transfer.id);out.putInt("qr_total",transfer.total);for(var chunk:transfer.chunks.entrySet())out.putString("qr_"+chunk.getKey(),chunk.getValue());}
    void scan(){new IntentIntegrator(this).setDesiredBarcodeFormats(IntentIntegrator.QR_CODE).setPrompt("Наведите камеру на QR настроек в расширении").setOrientationLocked(false).setBeepEnabled(false).initiateScan();}
    void receive(String raw){try{JSONObject value=transfer.accept(raw);if(value!=null)confirm(value);else{render();new AlertDialog.Builder(this).setTitle("QR принят").setMessage("Прочитано "+transfer.chunks.size()+" из "+transfer.total).setPositiveButton("Следующий QR",(d,w)->scan()).setNegativeButton("Позже",null).show();}}catch(Exception e){error(e.getMessage());}}
    void confirm(JSONObject value){new AlertDialog.Builder(this).setTitle("Перенести настройки?").setMessage("После входа эти настройки будут применены к подключённому аккаунту. Автоматизация останется остановленной.").setPositiveButton("Перенести",(d,w)->{pending=value;getSharedPreferences("onboarding",0).edit().putString("pending",value.toString()).apply();render();}).setNegativeButton("Отмена",null).show();}
    void error(String value){new AlertDialog.Builder(this).setTitle("Не удалось прочитать").setMessage(value).setPositiveButton("Готово",null).show();}
    @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);var qr=IntentIntegrator.parseActivityResult(code,result,data);if(qr!=null){if(qr.getContents()!=null)receive(qr.getContents());return;}if(code==10){render();return;}if(result!=RESULT_OK||data==null||data.getData()==null)return;try{if(code==30){try(InputStream input=getContentResolver().openInputStream(data.getData());ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=input.read(b))!=-1){if(out.size()+n>2*1024*1024)throw new IOException("Файл больше 2 МБ");out.write(b,0,n);}confirm(Settings.decode(out.toString("UTF-8")));}}else if(code==31){android.graphics.BitmapFactory.Options o=new android.graphics.BitmapFactory.Options();o.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(data.getData())){android.graphics.BitmapFactory.decodeStream(in,null,o);}o.inSampleSize=Math.max(1,Math.max(o.outWidth,o.outHeight)/1800);o.inJustDecodeBounds=false;android.graphics.Bitmap bitmap;try(InputStream in=getContentResolver().openInputStream(data.getData())){bitmap=android.graphics.BitmapFactory.decodeStream(in,null,o);}if(bitmap==null)throw new IOException("Нужна картинка с QR");int w=bitmap.getWidth(),h=bitmap.getHeight();int[] pixels=new int[w*h];bitmap.getPixels(pixels,0,w,0,0,w,h);bitmap.recycle();java.util.Map<DecodeHintType,Object> hints=new java.util.EnumMap<>(DecodeHintType.class);hints.put(DecodeHintType.TRY_HARDER,true);hints.put(DecodeHintType.POSSIBLE_FORMATS,java.util.Collections.singletonList(BarcodeFormat.QR_CODE));String resultText;try{resultText=new MultiFormatReader().decode(new BinaryBitmap(new HybridBinarizer(new RGBLuminanceSource(w,h,pixels))),hints).getText();}catch(NotFoundException e){hints.put(DecodeHintType.PURE_BARCODE,true);resultText=new MultiFormatReader().decode(new BinaryBitmap(new HybridBinarizer(new RGBLuminanceSource(w,h,pixels))),hints).getText();}receive(resultText);}}catch(Exception e){error(e instanceof NotFoundException?"QR на изображении не найден":e.getMessage());}}
}
